import {escapeHtml as esc,id} from './core.mjs';
import {createJourney,updateJourney,updateJourneyStep,addJourneyStep,journeyProgress,mentorReply} from './journeys-core.mjs';

// The public label is set at integration time; domain data does not depend on branding.
export const JOURNEY_LABEL='Mentra Impulso';
const tracks=Object.assign(Object.create(null),{
 discover:{label:'Quero começar do zero',short:'Encontrar um caminho',intro:'Você não precisa chegar com uma ideia pronta. Vamos olhar o que você sabe, o que busca e o que cabe agora.',icon:'leaf',example:'Trabalho, renda extra, uma mudança ou algo seu.',title:'Um começo que faça sentido para você.'},
 idea:{label:'Quero colocar minha ideia em prática',short:'Colocar uma ideia em prática',intro:'Tire a ideia da cabeça e transforme em um teste pequeno, com etapas que você consegue acompanhar.',icon:'idea',example:'De uma ideia solta a uma primeira experiência.',title:'Sua ideia merece um primeiro passo.'},
 ongoing:{label:'Quero organizar o que já comecei',short:'Organizar o que já comecei',intro:'Entenda o que está travando, escolha uma prioridade e organize as próximas ações, sem recomeçar do zero.',icon:'business',example:'Um projeto, trabalho, renda extra ou negócio em andamento.',title:'Mais direção para o que já está em movimento.'}
});
const contexts={undecided:'Ainda estou descobrindo',work:'Trabalho e carreira',income:'Renda extra',business:'Um negócio',personal:'Projeto pessoal'};
const statuses={active:'Em andamento',paused:'Pausado',completed:'Concluído'};
const stepStatuses={todo:'A fazer',doing:'Em andamento',done:'Concluída'};
const dateText=value=>value?value.split('-').reverse().join('/'):'Sem prazo definido';
const defaults=track=>({track,title:'',goal:'',context:'undecided',audience:'',resources:'',time:'15',skills:'',interests:'',barrier:'',priority:''});

export function createJourneysUI(ctx){
 const {getState,setState,save,toast,render,modal,closeModal,button,link,icon,heading,getRoute,goTo}=ctx;
 const copy=(demo,live)=>globalThis.mentraProduction?live:demo;const drafts={},mentorMessages=new Map();let pending=null,mentorBusy=false,mentorEpoch=0,mentorAbort=null;
 const journeys=()=>Array.isArray(getState().journeys)?getState().journeys:[];
 const find=key=>journeys().find(j=>j.id===key);
 const selected=()=>find(getRoute().split('/')[2]);
 const field=(label,name,value='',extra='',type='text')=>`<label for="journey-${name}">${label}</label><input id="journey-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
 const area=(label,name,value='',extra='')=>`<label for="journey-${name}">${label}</label><textarea id="journey-${name}" name="${name}" rows="3" ${extra}>${esc(value)}</textarea>`;
 const select=(label,name,options,value)=>`<label for="journey-${name}">${label}</label><select id="journey-${name}" name="${name}">${Object.entries(options).map(([v,t])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
 const error=(modalMode=false)=>`<p id="${modalMode?'journey-modal-error':'journey-page-error'}" class="form-error" role="alert" tabindex="-1"></p>`;
 const fail=(text,modalMode=false)=>{const node=document.querySelector(modalMode?'#journey-modal-error':'#journey-page-error');if(node){node.textContent=Array.isArray(text)?text.join(' '):text;node.focus?.({preventScroll:true});}else toast(Array.isArray(text)?text.join(' '):text);};
 function commit(result,{inModal=false,route='',focus=''}={}){
  if(!result.ok){fail(result.errors||'Não foi possível salvar. Revise os campos.',inModal);return false;}
  const before=getState();setState(result.state);
  if(save()===false){setState(before);fail('Não foi possível guardar neste navegador. Seu plano anterior foi mantido. Os campos continuam aqui para tentar novamente.',inModal);return false;}
  if(inModal)closeModal();if(route)goTo(route);else render();
  if(focus)document.querySelector(focus)?.focus?.({preventScroll:true});
  toast(result.duplicate?'Este plano já está salvo.':'Plano salvo neste navegador. Um passo de cada vez.');return true;
 }
 function renderHomeCard(){const active=journeys().find(j=>j.status==='active'),next=active?journeyProgress(active).nextStep:null;return `<section class="journey-home"><h2>Qual é o seu momento?</h2><div class="journey-home-choices">${Object.entries(tracks).map(([key,t])=>link(esc(t.label)+' '+icon('arrow'),'caminhos/novo/'+key,'text-link')).join('')}</div>${active?`<div class="journey-home-resume"><small>CONTINUE DE ONDE PAROU</small>${link(esc(next?.title||active.title)+' '+icon('arrow'),'caminhos/plano/'+active.id,'text-link')}</div>`:''}</section>`;}

 function card(j){const p=journeyProgress(j);return `<article class="journey-saved-card"><div class="journey-card-meta"><span>${esc(tracks[j.track]?.short||'Meu plano')}</span><b class="badge">${esc(statuses[j.status]||'Em andamento')}</b></div><h3>${esc(j.title)}</h3><p>${esc(j.goal)}</p><div class="progress"><i style="width:${p.percent}%"></i></div><div class="journey-card-footer"><span>${p.done} de ${p.total} etapas</span>${link('Continuar '+icon('arrow'),'caminhos/plano/'+j.id,'text-link')}</div></article>`;}
 function renderHub(){return heading('DA CLAREZA À AÇÃO',JOURNEY_LABEL,'Você não precisa fazer tudo. Só encontrar um começo possível.')+`<section class="journey-intro"><div><span class="eyebrow">TRÊS JEITOS DE COMEÇAR</span><h2>Encontre seu caminho.<br><em>Transforme ideias em ação.</em></h2><p>Trabalho, renda extra, um projeto pessoal ou um negócio. Escolha o momento em que você está, e vamos organizar um plano que caiba na sua vida.</p><div class="journey-intro-tags"><span>Seu contexto</span><span>Uma prioridade</span><span>Próximos passos</span></div></div><aside><img src="assets/mentra-face.png" alt="Rosto da Mentra" width="1280" height="1280"><p>“Vamos transformar o que está solto em um primeiro passo.”</p><small>Mentoria roteirizada · DEMO</small></aside></section><section class="journey-start"><div class="section-head"><h2>Qual é o seu momento?</h2><span class="muted small">Você pode criar mais de um plano</span></div><div class="journey-track-grid">${Object.entries(tracks).map(([key,t],i)=>link(`<span class="journey-track-top"><b>0${i+1}</b><span class="round-icon">${icon(t.icon)}</span></span><h3>${t.label}</h3><p>${t.example}</p><span class="text-link">Começar por aqui ${icon('arrow')}</span>`,'caminhos/novo/'+key,'journey-track-card')).join('')}</div></section>${journeys().length?`<section class="journey-projects"><div class="section-head"><h2>Seus planos, no seu ritmo</h2><span class="small muted">Salvos neste navegador</span></div><div class="journey-saved-grid">${journeys().map(card).join('')}</div></section>`:''}<section class="journey-legacy"><span class="round-icon">${icon('calendar')}</span><div><h2>Projetos pessoais também têm espaço.</h2><p>Abra os caminhos anteriores, incluindo o progresso que você já tinha. Criar um plano novo não apaga o antigo.</p>${link('Projetos pessoais e caminhos anteriores '+icon('arrow'),'projetos','text-link')}</div></section><div class="notice warm">${icon('info')} Demonstração com dados fictícios. Os planos são sugestões de um roteiro local, não de IA real. Você revisa e decide; não há garantia de emprego, renda ou resultado.</div>`;}
 function renderStart(track){const t=tracks[track];if(!t)return missing();const d=drafts[track]||defaults(track);return link(icon('back')+' Voltar aos caminhos','caminhos','back-link')+heading(t.short.toUpperCase(),t.title,t.intro)+`<div class="journey-onboarding"><section class="card journey-form-card"><div class="journey-form-progress"><b>1. Seu momento</b><span>2. Revisar o plano</span><span>3. Começar</span></div><form id="journey-start-form" data-track="${track}">${select('Em qual área você quer avançar?','context',contexts,d.context)}${track==='discover'?area('O que você gostaria de mudar ou conquistar?','goal',d.goal,'required maxlength="500" placeholder="Ex.: encontrar uma possibilidade de renda que caiba na minha rotina"')+area('O que você sabe fazer ou gosta de fazer? (opcional)','skills',d.skills,'maxlength="500" placeholder="Vale uma habilidade do dia a dia. Se ainda não souber, pode deixar em branco."'):field(track==='idea'?'Qual ideia você quer colocar em prática?':'O que você já começou?','title',d.title,'required maxlength="160" placeholder="Dê um nome simples ao seu plano"')+area('Qual seria um primeiro avanço importante?','goal',d.goal,'required maxlength="500"')}${track==='idea'?area('Quem poderia se beneficiar? (opcional)','audience',d.audience,'maxlength="300" placeholder="Se ainda não sabe, essa pode ser uma das primeiras perguntas."'):track==='ongoing'?area('O que está travando agora?','barrier',d.barrier,'required maxlength="500"')+field('O que merece atenção primeiro? (opcional)','priority',d.priority,'maxlength="300"'):''}${area('Com quais recursos você já pode contar? (opcional)','resources',d.resources,'maxlength="500" placeholder="Ex.: celular, experiência, uma hora livre ou alguém com quem conversar"')}${select('Quanto tempo cabe em cada pequeno passo?','time',{'5':'5 minutos','15':'15 minutos','30':'30 minutos','60':'1 hora'},d.time)}${error()}<p class="journey-form-note">${copy('Use exemplos fictícios. O plano só será salvo','O plano só será salvo')} depois de você revisar e confirmar. Você poderá ajustar o plano e as etapas depois.</p><button class="primary" type="submit">Organizar meus próximos passos ${icon('arrow')}</button></form></section><aside class="stack"><section class="card tinted"><span class="round-icon">${icon('spark')}</span><h2>Clareza antes<br>de cobrança.</h2><p>Você vai receber uma sugestão com quatro etapas, uma próxima ação e espaço para escolher seus prazos.</p><ul class="journey-checks"><li>Sem exigir uma ideia perfeita</li><li>Sem gasto inicial obrigatório</li><li>Sem mudar sua agenda ou seu dinheiro</li></ul></section><div class="notice subtle">${copy('Mentoria demonstrativa: regras locais organizam o que você informar. Não há conversa com uma IA real nem análise de mercado.','Regras locais sugerem as etapas iniciais para você revisar. Depois de salvar, você pode pedir orientação à IA sobre o plano; isso consome a cota da assinatura.')}</div></aside></div>`;}
 function renderPlan(j){if(!j)return missing();const p=journeyProgress(j),next=p.nextStep,reply=mentorMessages.get(j.id);return link(icon('back')+' Todos os meus caminhos','caminhos','back-link')+heading(tracks[j.track]?.short.toUpperCase()||'MEU PLANO',esc(j.title),esc(j.goal),button(icon('edit')+' Editar plano','journey-edit','outline',`data-id="${esc(j.id)}"`))+`<div class="journey-plan-meta"><span class="badge">${esc(statuses[j.status])}</span><span>${esc(contexts[j.context]||contexts.undecided)}</span><span>${esc(j.time)} minutos por passo</span><span>${p.done}/${p.total} etapas concluídas</span></div><div class="progress large"><i style="width:${p.percent}%"></i></div>${error()}<div class="journey-plan-layout"><div class="stack"><section class="journey-next-action"><span class="eyebrow">${j.status==='paused'?'PLANO PAUSADO · QUANDO QUISER RETOMAR':'SEU PRÓXIMO PASSO'}</span><h2>${next?esc(next.title):'Você concluiu as etapas deste plano.'}</h2><p>${next?esc(next.description):'Reveja o que aprendeu. Você pode reabrir uma etapa ou acrescentar uma nova ação.'}</p><span>${next?dateText(next.dueDate):'Progresso registrado na demonstração'}</span>${next?button('Ajustar ação ou prazo '+icon('edit'),'journey-edit-step','outline',`data-id="${esc(j.id)}" data-step="${esc(next.id)}"`):''}</section><section class="card"><div class="section-head"><h2>Seu plano de ação</h2>${button(icon('plus')+' Etapa','journey-add-step','outline',`data-id="${esc(j.id)}"`)}</div><ol class="journey-step-list">${j.steps.map((s,i)=>`<li class="${s.status==='done'?'is-done':''}"><button class="journey-step-toggle" data-action="journey-toggle-step" data-id="${esc(j.id)}" data-step="${esc(s.id)}" aria-label="${s.status==='done'?'Reabrir':'Concluir'} etapa ${i+1}: ${esc(s.title)}" aria-pressed="${s.status==='done'}">${s.status==='done'?icon('check'):i+1}</button><div><span class="small-label">${esc(stepStatuses[s.status])} · ${dateText(s.dueDate)}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p>${button('Editar etapa','journey-edit-step','text-link',`data-id="${esc(j.id)}" data-step="${esc(s.id)}"`)}</div></li>`).join('')}</ol></section></div><aside class="stack"><section class="card journey-mentor"><div class="journey-mentor-heading"><img src="assets/mentra-face.png" alt="" width="1280" height="1280"><div><span class="eyebrow">MENTRA AO SEU LADO</span><h2>Um apoio para começar.</h2></div></div><p class="small muted">${copy('Mentoria roteirizada · DEMO. Use os atalhos ou escreva uma pergunta. A sugestão não altera seu plano.','Orientação por IA. Ao solicitar, o DeepSeek recebe seu pedido, os dados deste plano e um resumo do perfil, tarefas, agenda e finanças da sua conta. Saúde e arquivos não são anexados automaticamente. A orientação não altera suas etapas.')}</p><div class="journey-mentor-prompts">${[['start','Por onde começo?'],['simplify','Como deixar mais simples?'],['priority','O que priorizar?']].map(([key,title])=>button(title,'journey-mentor-prompt','outline',`data-id="${esc(j.id)}" data-prompt="${key}"`)).join('')}</div><form id="journey-mentor-form" data-id="${esc(j.id)}"><label for="journey-question">O que está te deixando em dúvida?</label><textarea id="journey-question" name="question" rows="3" maxlength="600" required placeholder="Ex.: tenho pouco tempo para começar"></textarea><button class="primary" type="submit">${copy('Pedir uma orientação de exemplo','Pedir orientação à IA')}</button></form><div id="journey-mentor-reply" class="journey-mentor-reply" role="status" aria-live="polite" tabindex="-1">${reply?renderReply(reply):'<p>Você continua no controle. Escolha uma pergunta para explorar.</p>'}</div></section><section class="card"><h2>Seu ponto de partida</h2><dl class="journey-context">${[['Objetivo',j.goal],['Prioridade',j.priority],['O que está travando',j.barrier],['Para quem',j.audience],['Habilidades',j.skills],['Interesses',j.interests],['Recursos disponíveis',j.resources]].filter(([,v])=>v).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="small muted">Sem garantia de resultado. As etapas são um roteiro editável, não uma avaliação profissional.</p></section></aside></div>`;}
 const renderReply=reply=>`<span class="small-label">${copy('SUGESTÃO ROTEIRIZADA','ORIENTAÇÃO DA IA · REVISE')}</span><p>${esc(typeof reply==='string'?reply:reply.text||reply.message||'Escolha uma etapa pequena e ajuste ao seu contexto.')}</p>${reply?.suggestion?`<p><b>Para testar:</b> ${esc(typeof reply.suggestion==='string'?reply.suggestion:reply.suggestion.description||reply.suggestion.title||'')}</p>`:''}<small>Revise antes de aplicar. Nada foi alterado automaticamente.</small>`;
 async function answer(j,prompt){if(mentorBusy)return;mentorBusy=true;const epoch=mentorEpoch,dataEpoch=globalThis.window?.mentraDataEpoch||0;let reply;const node=document.querySelector('#journey-mentor-reply');if(node)node.textContent='Preparando orientação…';try{if(globalThis.mentraPlatform){if(!await window.mentraSave.flush())throw Error('Resolva a sincronização antes de consultar a IA.');if(epoch!==mentorEpoch||dataEpoch!==(globalThis.window?.mentraDataEpoch||0))return;mentorAbort=new AbortController();const {send}=await import('./platform.mjs');const content=({start:'Por onde começo neste plano?',simplify:'Como deixar este plano mais simples?',priority:'O que devo priorizar neste plano?'})[prompt]||String(prompt).slice(0,600);const result=await send('chat',{journeyId:j.id,messages:[{role:'user',content}]},'POST',{signal:mentorAbort.signal});if(epoch!==mentorEpoch||dataEpoch!==(globalThis.window?.mentraDataEpoch||0))return;if(result.usage)window.mentraPlatform.usage=result.usage;reply={text:result.text};}else reply=mentorReply(j,prompt);if(epoch!==mentorEpoch||dataEpoch!==(globalThis.window?.mentraDataEpoch||0))return;mentorMessages.set(j.id,reply);const current=document.querySelector('#journey-mentor-reply');if(current){current.innerHTML=renderReply(reply);current.focus?.({preventScroll:true});}}catch(error){if(epoch===mentorEpoch&&error.name!=='AbortError'){toast(error.message);if(node)node.textContent=error.message;}}finally{mentorBusy=false;mentorAbort=null;}}

 function missing(){return heading('MEUS CAMINHOS','Este plano não está neste navegador.','Ele pode estar em outro aparelho ou ainda não ter sido salvo.')+link('Voltar aos caminhos','caminhos','primary');}
 function renderPage(){const [,area,key]=getRoute().split('/');return area==='novo'?renderStart(key):area==='plano'?renderPlan(find(key)):renderHub();}
 function editPlan(j){modal('Ajustar meu plano',`<form id="journey-edit-form" data-id="${esc(j.id)}">${field('Nome do plano','title',j.title,'required maxlength="160"')}${area('Objetivo','goal',j.goal,'required maxlength="500"')}${field('Prioridade','priority',j.priority,'maxlength="300"')}${area(j.track==='ongoing'?'O que está travando':'O que está travando (opcional)','barrier',j.barrier,(j.track==='ongoing'?'required ':'')+'maxlength="500"')}${area('Recursos disponíveis (opcional)','resources',j.resources,'maxlength="500"')}<details class="journey-edit-context"><summary>Revisar meu contexto e ponto de partida</summary>${select('Área em que quero avançar','context',contexts,j.context)}${area('Quem pode se beneficiar (opcional)','audience',j.audience,'maxlength="300"')}${area('Habilidades (opcional)','skills',j.skills,'maxlength="500"')}${area('Interesses (opcional)','interests',j.interests,'maxlength="500"')}</details>${select('Tempo por passo','time',{'5':'5 minutos','15':'15 minutos','30':'30 minutos','60':'1 hora'},j.time)}${select('Status do plano','status',statuses,j.status)}<p class="small muted">Concluir exige todas as etapas concluídas. Mudar estes dados não recria nem apaga as etapas.</p>${error(true)}<div class="modal-actions">${button('Cancelar','close-modal','outline')}<button type="submit" class="primary">Salvar ajustes</button></div></form>`);}
 function editStep(j,step){modal(step?'Editar etapa':'Adicionar uma etapa',`<form id="journey-step-form" data-id="${esc(j.id)}" data-step="${esc(step?.id||'')}">${field('Uma ação clara','title',step?.title||'','required maxlength="160"')}${area('Como começar','description',step?.description||'','required maxlength="600"')}${field('Prazo escolhido por você (opcional)','dueDate',step?.dueDate||'','','date')}${select('Status da etapa','status',stepStatuses,step?.status||'todo')}${error(true)}<div class="modal-actions">${button('Cancelar','close-modal','outline')}<button type="submit" class="primary">Salvar etapa</button></div></form>`);}
 function review(raw){const creationId=id(),result=createJourney(getState(),raw,creationId);if(!result.ok){fail(result.errors);return;}pending={raw,creationId};const j=result.journey;modal('Seu primeiro plano, para revisar',`<div class="journey-review"><span class="eyebrow">SUGESTÃO DEMONSTRATIVA · VOCÊ DECIDE</span><h3>${esc(j.title)}</h3><p>${esc(j.goal)}</p><ol>${j.steps.map(s=>`<li><b>${esc(s.title)}</b><p>${esc(s.description)}</p></li>`).join('')}</ol><p class="small muted">Prazos ficam em aberto para você escolher. Nenhuma tarefa, evento ou lançamento será criado em outra área.</p></div>${error(true)}<div class="modal-actions">${button('Voltar e ajustar','journey-back','outline')}${button('Confirmar e guardar plano','journey-confirm','primary')}</div>`);}
 function handleSubmit(form){if(!form.id.startsWith('journey-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}const raw=Object.fromEntries(new FormData(form)),j=find(form.dataset.id);
  if(form.id==='journey-start-form'){const track=form.dataset.track;if(!tracks[track])return true;drafts[track]={...defaults(track),...raw,track};review(drafts[track]);}
  else if(form.id==='journey-edit-form'&&j)commit(updateJourney(getState(),j.id,raw),{inModal:true,focus:`[data-action="journey-edit"][data-id="${j.id}"]`});
  else if(form.id==='journey-step-form'&&j)commit(form.dataset.step?updateJourneyStep(getState(),j.id,form.dataset.step,raw):addJourneyStep(getState(),j.id,raw),{inModal:true,focus:form.dataset.step?`[data-action="journey-edit-step"][data-step="${form.dataset.step}"]`:`[data-action="journey-add-step"][data-id="${j.id}"]`});
  else if(form.id==='journey-mentor-form'&&j){if(raw.question.trim())answer(j,raw.question);}
  return true;
 }
 function handleClick(action,data){if(!action.startsWith('journey-'))return false;const j=find(data.id);
  if(action==='journey-confirm'&&pending){const p=pending,result=createJourney(getState(),p.raw,p.creationId);if(commit(result,{inModal:true,route:'caminhos/plano/'+p.creationId})){delete drafts[p.raw.track];pending=null;}}
  else if(action==='journey-back'){pending=null;closeModal();render();document.querySelector('#journey-start-form input,#journey-start-form textarea,#journey-start-form select')?.focus?.();}
  else if(action==='journey-edit'&&j)editPlan(j);
  else if(action==='journey-edit-step'&&j){const step=j.steps.find(s=>s.id===data.step);if(step)editStep(j,step);}
  else if(action==='journey-add-step'&&j)editStep(j);
  else if(action==='journey-toggle-step'&&j){const step=j.steps.find(s=>s.id===data.step);if(step)commit(updateJourneyStep(getState(),j.id,step.id,{status:step.status==='done'?'todo':'done'}),{focus:`[data-action="journey-toggle-step"][data-step="${step.id}"]`});}
  else if(action==='journey-mentor-prompt'&&j)answer(j,data.prompt);
  return true;
 }
 function handleInput(event){const form=event.target.closest?.('#journey-start-form');if(form&&tracks[form.dataset.track])drafts[form.dataset.track]={...defaults(form.dataset.track),...Object.fromEntries(new FormData(form)),track:form.dataset.track};}
 return {renderPage,renderHomeCard,handleClick,handleSubmit,handleInput,cancelPending:()=>{pending=null;},routeChanged:()=>{pending=null;mentorEpoch++;mentorAbort?.abort();}};
}
